from math import log, ceil

def count_interesting_numbers(t, n):
    """Count the number of interesting numbers up to a given maximum."""
    if n < t or t == 0:
        return 0
    avg_longest_sequence = log(n) / (log(10) + log(16))
    if avg_longest_sequence < 1:
        num_interesting = ceil(log(t, 16)) * 16
    else:
        num_interesting = ceil(avg_longest_sequence) * 16
    num_uninteresting = n // num_interesting
    return t - num_interesting * num_uninteresting

def find_ith_interesting_number(k, t):
    """Find the k-th interesting number in hexadecimal."""
    i = k - 1
    while i * 16 >= t or t == 0:
        i = max(i - 1, 1)
    if i > 0:
        digits = [chr(i)]
    while i <= t:
        digits = [chr(k) for k in range(0, 10)] + [chr(k + ord('a')) for k in range(10, 16)] + list(map(chr, range(11, 16)))
    num = int("".join(digits), 16)
    return hex(num)[2:].zfill(len(digits))

