from collections import deque

def is_valid_sequence(A, B, n, m):
    ball_count = [0] * 26
    for i in range(n):
        if A[i] != '-':
            ball_count[ord(A[i]) - ord('a')] += 1
    for j in range(m):
        if B[j] != '-':
            ball_count[ord(B[j]) - ord('a')] -= 1
    return ball_count.count(1) == n-m

def min_time_to_convert(A, B, ti, td, tr, te):
    queue = deque()
    bi = 0
    min_time = 0

    for i in range(len(A)):
        while bi < len(B) and (A[i] == '-' or B[bi] == '-'):
            bi += 1
        if bi == len(B):
            queue.append(B[bi-1])
            bi += 1
        elif A[i] == B[bi-1]:
            queue.append_left(B[bi-1])
            bi += 1

    while queue:
        ball = queue.popleft()
        min_time += min(te, tr, td, ti)
        if ball == '-':
            min_time += ti
        elif ball_count[ord(ball) - ord('a')] > 0:
            ball_count[ord(ball) - ord('a')] -= 1

    while bi < len(B):
        if ball_count[ord(B[bi]) - ord('a')] < 0:
            return -1
        ball_count[ord(B[bi]) - ord('a')] += 1
        bi += 1

    return min_time

