def count_palindromes(N, K, chars):
    count = 0
    for i in range(1, K+1):
        j = i + 1
        while j <= K and chars[j] == chars[i]:
            j += 1
        for m in range(0, i):
            left = i - m
            right = j - (N - left)
            if left >= right:
                count += 1
    return count

