from heapq import heappush, heappop

def insert_point(points_set, x, y):
    points_set.add((x, y))
    return len(points_set)

def remove_point(points_set, x, y):
    points_set.remove((x, y))
    return len(points_set)

def find_symmetric_points(left, right):
    heapq = []
    for point in left:
        for point in right:
            heappush(heapq, abs(point))

    min_points = 0
    opposite_pairs = 0

    while len(heapq) >= 2:
        left_side = heappop(heapq)
        right_side = heappop(heapq)
        if left_side >= right_side:
            heappush(heapq, left_side - right_side)
        else:
            heappush(heapq, right_side - left_side)
            min_points += 2

    return min_points + opposite_pairs

def process_queries(q, queries):
    points_set = set()
    result = []
    for query in queries:
        t, x, y = query
        if t == 1:
            result.append(insert_point(points_set, x, y))
        elif t == 2:
            result.append(remove_point(points_set, x, y))
        else:
            minimum_points = find_symmetric_points(points_set, points_set)
            result.append(minimum_points)
    return result

