def nth_interesting_hex(k, t):
    if t == 1:
        # If t is 1, the interesting numbers will be the same as the decimal numbers
        return bin(k)[2:]

    total_count = k * (t**6)  # Calculate the total count of interesting numbers
    half_term = total_count // 2  # Half of the total count, excluding leading zeros

    reversed_hex = hex(switch_reverse_direction_fix_len(half_term))[2:]  # Reverse the hex and process

    tmp = int('0x' + reversed_hex, 16)  # Convert the reversed hex to decimal
    first_digit_n = get_count(tmp)  # Count the number of chosen digits in the first byte

    long_word_len = (first_digit_n // (first_digit_n % 2)) / get_first_word_len(tmp)  # Calculate the length of the long word

    if first_digit_n % 2 == 0:
        first_digit = hex(switch_reverse_direction_fix_len(first_digit_n))[2:]  
    else:
        first_digit = hex(switch_reverse_direction_fix_len(first_digit_n - 1))[2:]

    return switch_reverse_direction_fix_len(do_method(first_digit, long_word_len))[2:]

def do_method(first_digit, long_word_len):
