    return bin(long_word_len + 6)[2:]

def switch_reverse_direction_fix_len(number):
    return int(number[::-1])

def stable_subword_len(number):
    return [int(s) for s in number[::-1] if s.isalpha()][-2:]

def get_first_word_len(number):
    for digit in hex(number):
        if not digit.isdigit():
