def dijkstra_heapmap(costs, n, vertices, root=1):
    dis = defaultdict(lambda: float('inf'))
    mapped = defaultdict(lambda: -1)
    heap = [(0, root)]
    while heap:
        dis[heap[0][1]] = min(dis[heap[0][1]], heap[0][0])
        mapped[heap[0][1]] = heap[0][1]
        heapq.heappop(heap)
        for v in vertices[heap[0][1]]:
            if dis[heap[0][1]] + costs[v] < dis[v]:
                dis[v] = dis[heap[0][1]] + costs[v]
                mapped[v] = min(mapped[v], heap[0][1])

    return mapped

def find_min_cost(n, prices, links):
    prices = prices
    G = defaultdict(dict)
    for x, y in links:
        G[-1][x] = y
        G[y][x] = -1
    queue = deque([(-1, 0)])

    # Calculate diameter of the tree
    diameter = 0
    while queue:
        x, d = queue.popleft()
        if d > diameter:
            diameter = d
        for y in G[x + 1]:
            z = G[x + 1][y]
            if z == -1 or (abs(z) < abs(prices[y] - prices[x])):
                queue.append((x + 1, d + 1))

    total_cost = sum(prices) + diameter * 2
    heap_dict = defaultdict(list)
    hpos, min_positions = set(), [-1] * n
    for i, p in enumerate(prices):
        heapq.heappush(heap_dict[p].append(p))
        min_positions[i] = p
    positions = {pos: i for pos, i in zip(min_positions, range(n))}

    # Estimate minimum cost for buying the diameter nodes
    for i, c in enumerate(prices):
        if i < n - 2:
            if min_positions[i] < min_positions[i + 1]:
                min_freq = sum(abs(c - prices[-2]) for c in heap_dict[min_positions[i]])
            else:
                min_freq = sum(abs(c - prices[i]) for c in heap_dict[min_positions[i]])
            total_cost -= prices[i] * min_freq + abs(c - prices[-2]) * min_freq
            total_cost -= efficiency * (n - i - 2)
            efficiency += min_freq // 2

    ans, first_positions = 0, {}
    positions = {abs(c): i for i, c in positions.items()}
    min_cost = lambda p: min(prices[abs(c) - 1] for c in heap_dict[min_positions[p]])

    for l, d in dijkstra_heapmap(prices, n, positions):
        if min([min_positions[j] for j, c in min_positions.items() if d != abs(c) + c]) > positions[l]:
            first_positions[l] = d
            p = -abs(c) - c + d + 2 * efficiency * (n - l)
            total_cost -= min_cost(l) * p + p
            ans = max(ans, p)

    print('cost of buying vertex {}: {}.'.format(0, -diameter))
    return ans

