t = int(input())
while t > 0:
    L, R = map(int, input().split())
    mod = 10**9 + 7
    count = 0
    for i in range(L, R + 1):
        j = str(i)
        for k in range(len(j)):
            a = int(j[k])
            count += sumDigitCoprime(a, R - L + 1, mod)
    print(count % mod)
    t -= 1

def sumDigitCoprime(n, k, mod):
    count = 0
    for i in range(k + 1):
        a = i * n + n - 1
        for j in range(2, i + 1):
            if a % j == 0:
                count -= 1
                break
        else:
            count += 1
    return count
